s.strip();               // "Hello, World!" (современный аналог, лучше работает с Unicode)

// Замена
s.replace("World", "Java");  // "  Hello, Java!  "

// Разбиение и объединение
String csv = "apple,banana,cherry";
String[] parts = csv.split(",");  // ["apple", "banana", "cherry"]

String joined = String.join(" | ", "Вика", "Аня", "Маша"); // "Вика | Аня | Маша"

// Проверки
"".isEmpty();            // true (длина 0)
"   ".isBlank();         // true (только пробелы, Java 11+)
"123".matches("\\d+");   // true (регулярное выражение: только цифры)

// Преобразования типов
String.valueOf(42);      // "42"
Integer.parseInt("123"); // 123 (String → int)
Double.parseDouble("3.14"); // 3.14
```

